export default function generateCode(pluginPasses, file) {
  const {
    opts,
    ast,
    code,
    inputMap
  } = file;
  const generatorOpts = opts.generatorOpts;
  generatorOpts.inputSourceMap = inputMap?.toObject();
  const results = [];
